      SUBROUTINE RECKONCC     RUNS THROUGH BEAM LINE STORING AVERAGES OF CONSTRAINED QUANTITIESC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM31A.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'LXRAN.CIN'C      CALL INITZE    1 I = ISTOR(NUM)      TYPE = IDATA(I)      IF (TYPE .GE. 82 .AND. TYPE .LE. 86) GO TO 70      IF (TYPE .LE. 0 .OR. TYPE .GE. 50) GO TO 810C      CALL SKETCH(NUM)      CALL DEPICT      IF (.NOT. ATWE) GO TO 810      IF (DOPARS .AND. TYPE .NE. 23 .AND. TYPE .NE. 30 .AND.     1    TYPE .NE. 9 .AND. TYPE .NE. 24 .AND. TYPE .NE. 31) GO TO 810CC     POSSIBLE INITIAL MISALIGNMENTSC      CALL POSSIMCC     SIMPLE ELEMENTSC      IF (RABL .AND. WFRN) GO TO 200      IF (RABL) GO TO 100   70 TYPEC = TYPE      LXRAN = TYPE .LT. 50      CALL ELICIT      IF (FLUSHL) GO TO 900      IF (TYPE .LE. 0) GO TO 810      IF (TYPE .GE. 50) GO TO 810CC     UPDATE USED TO MARK BEGINNING OF MISALIGNMENTC      IF (TYPE .NE. 6 .AND. TYPE .NE. 37) GO TO 810      CALL UPMARK      IF (FLUSHL) GO TO 900      GO TO 810CC     SIMPLE ELEMENTS WITH POSSIBLE TILTC  100 IF (TYPE .EQ. 2 .OR. TYPE .EQ. 4) GO TO 150      CALL ELTILT      IF (FLUSHL) GO TO 900      GO TO 800CC     BENDING MAGNETS WITH FRINGE FIELD SPECIFIED BY SEPARATE ELEMENTC  150 CALL EL242      IF (FLUSHL) GO TO 900      GO TO 800CC     COMPOUND ELEMENTSC  200 CALL ELCOMP      IF (FLUSHL) GO TO 900      GO TO 800CC     LOOP THROUGH MISALIGNMENTS BY NAMEC  800 IF (NMISRB .NE. 0) CALL AGENDR(1)CC     ADVANCE TO NEXT ELEMENTC  810 IF (MKG .AND. NUM .EQ. NMARKE) CALL AGENDA(2)      IF (ALGR .AND. NUM .EQ. NMISRE) CALL AGENDR(2)      NUM = NUM + NDIF      IF (.NOT. MKG .AND. NUSE .NE. 0 .AND. NUM .GT. NUSE) GO TO 900      IF (NUM .LE. NEL) GO TO 1  900 RETURN      END